def closeMosaic(host=socketAddress, port=socketPort, restVer="1.0.1"):
    """
    close Airmosaic running Harness session on the given port

    :param host: IP address at which Airmosaic is listening
    :param port: port at which Airmosaic is listening
    :return: {'result':result, 'error':error},
             where *result* can be *success* or *failed* and
             *error* is the failure cause description.
    """
    if restVer.startswith('1.'):
        # workaround closeAirMosaic still require session id
        res = openTestSession(host, port, restVer)
        if res['result'] == 'success':
            tmp_ses_id = res['sessionId']
        else:
            return {
                'result': 'failed',
                'error': "Failed close Airmosaic, can't get a valid session Id (err={0})".format(res['error'])
            }
        return closeAirMosaic(tmp_ses_id, host=host, port=port, restVer=restVer)
    pe_log(json_output, json_buffer,
           '*DEBUG* pymosaic.closeMosaic(): reply in legacy mode.')
    airmosaic_cmd = json.dumps({'cmd': 'closeAirmosaic', 'params': {}})
    req = Request('http://%s:%s/amJsonInterface' % (host, port),
                  airmosaic_cmd.encode("utf-8"), headers)

    try:
        res = urlopen(req, timeout=URLOPEN_TIMEOUT)
        return json.load(res)
    except URLError as pe_err:
        return {'result': 'success', 'error': ''}
    except Exception as pe_err:
        #pe_log(json_output, json_buffer,
        #       "*DEBUG* pymosaic.closeMosaic(): complete stack:\n{0}".format(traceback.format_exc()))
        pe_log(json_output, json_buffer,
            "*DEBUG* pymosaic.closeMosaic(): AM closed with error {0} - {1}".format(type(pe_err).__name__, pe_err.args))
        return {'result': 'success', 'error': ''}


def openTestSession(host=socketAddress, port=socketPort, restVer="1.0.1"):
    """
    Open a new test session.

    :param host: IP address at which Airmosaic is listening
    :param port: port at which Airmosaic is listening
    :param restVer: API REST version to user for request to HARNESS
    :return: {'result':result, 'error':error},
             where *result* can be *success* or *failed* and
             *error* is the failure cause description.
    """
    print (host,port)
    if restVer.startswith('1.'):
        return testSession(host=host, port=port, method="POST", restVer=restVer)
    pe_log(json_output, json_buffer,
           '*DEBUG* pymosaic.openTestSession(): reply in legacy mode.')
    airmosaic_cmd = json.dumps({'cmd': 'openTestSession', 'params': {}})
    req = Request('http://%s:%s/amJsonInterface' % (host, port),
                  airmosaic_cmd.encode("utf-8"), headers)
    try:
        res = urlopen(req, timeout=URLOPEN_TIMEOUT).read().decode('utf-8')
        return json.loads(res)
    except URLError as pe_err:
        return {'result': 'failed', 'error': str(pe_err.reason)}
    except Exception as pe_err:
        return {'result': 'failed', 'error': str(pe_err)}


def closeTestSession(session_id, host=socketAddress, port=socketPort, restVer="1.0.1"):
    """
    Close test session with the given session_id

    :param sessionId: session_id of the test session to be closed
    :param host: IP address at which Airmosaic is listening
    :param port: port at which Airmosaic is listening
    :return: {'result':result, 'error':error},
             where *result* can be *success* or *failed* and *error* is the failure cause.
    """
    if restVer.startswith('1.'):
        return testSession(host=host, port=port, method="DELETE", session_id=session_id, restVer=restVer)
    pe_log(json_output, json_buffer,
           '*DEBUG* pymosaic.closeTestSession(): reply in legacy mode.')
    airmosaic_cmd = json.dumps({
        'cmd': 'closeTestSession',
        'params': {
            'sessionId': session_id
        }
    })
    req = Request('http://%s:%s/amJsonInterface' % (host, port),
                  airmosaic_cmd.encode('utf-8'), headers)
    try:
        res = urlopen(req, timeout=URLOPEN_TIMEOUT).read().decode('utf-8')
        pe_log(json_output, json_buffer,
               '*DEBUG* pymosaic.closeTestSession(): urlopen.res={0}'.format(json.loads(res)))
        return json.loads(res)
    except URLError as pe_err:
        return {'result': 'failed', 'error': str(pe_err.reason)}
    except Exception as pe_err:
        return {'result': 'failed', 'error': str(pe_err)}


def storeZipArchive(session_id,
                    inzip,
                    outzip,
                    host=socketAddress,
                    port=socketPort,
                    restVer="1.0.1"):
    """
    Load zip file with Airmosaic cfg and scenario files and store it as *outzip*

    :param sessionId: session_id of the current test session
    :param inzip: path to a zip compressed archive containing all the needed Airmosaic cfg and scenario files
    :param outzip: name to be given to the *inzip* file once saved in Airmosaic temporary folder (e.g.: 'cfg.zip')
    :param restVer: API REST version to user for request to HARNESS
    :param host: IP address at which Airmosaic is listening
    :param port: port at which Airmosaic is listening
    :return: {'result':result, 'error':error},
             where *result* can be *success* or *failed* and
             *error* is the failure cause description.

    """
    if restVer.startswith('1.'):
        return zipArchive(session_id, inzip, 'test1', host=host, port=port, restVer=restVer)
    pe_log(json_output, json_buffer,
           '*DEBUG* pymosaic.storeZipArchive(): reply in legacy mode.')
    try:
        with open(inzip, 'rb') as zip_file:
            encodedZip = base64.b64encode(zip_file.read()).decode('utf-8')
        airmosaic_cmd = json.dumps({
            'cmd': 'storeZipArchive',
            'params': {
                'sessionId': session_id,
                'zipArchive': encodedZip,
                'filename': outzip
            }
        })
        req = Request('http://%s:%s/amJsonInterface' % (host, port),
                      airmosaic_cmd.encode('utf-8'), headers)
        try:
            res = urlopen(req, timeout=URLOPEN_TIMEOUT).read().decode('utf-8')
            return json.loads(res)
        except URLError as pe_err:
            return {'result': 'failed', 'error': str(pe_err.reason)}
        except Exception as pe_err:
            return {'result': 'failed', 'error': str(pe_err)}
    except IOError:
        return {'result': 'failed', 'error': 'Cannot open %s' % inzip}


def setOptions(session_id, options, host=socketAddress, port=socketPort, restVer="1.0.1"):
    """
    Set Airmosaic options

    :param sessionId: session_id of the current test session
    :param options: dictionary with *parameter*/*value* pairs of options to be set (e.g.: {'enableAMM':True})
    :param host: IP address at which Airmosaic is listening
    :param port: port at which Airmosaic is listening
    :return: {'result':result, 'error':error},
             where *result* can be *success* or *failed* and
             *error* is the failure cause description.
    """
    if restVer.startswith('1.'):
        if 'enableAMM' in options:
            opt_amm = options['enableAMM'].lower()
        else:
            opt_amm = ""
        if 'clockTimer' in options:
            opt_timer = options['clockTimer']
        else:
            opt_timer = ""
        return amOptions(session_id, enableAMM=opt_amm, clockTimer=opt_timer, host=host, port=port, restVer=restVer)
    pe_log(json_output, json_buffer,
           '*DEBUG* pymosaic.setOptions(): reply in legacy mode.')
    airmosaic_cmd = json.dumps({
        'cmd': 'setOptions',
        'params': {
            'sessionId': session_id,
            'options': options
        }
    })
    req = Request('http://%s:%s/amJsonInterface' % (host, port),
                  airmosaic_cmd.encode('utf-8'), headers)
    try:
        res = urlopen(req, timeout=URLOPEN_TIMEOUT).read().decode('utf-8')
        return json.loads(res)
    except URLError as pe_err:
        return {'result': 'failed', 'error': str(pe_err.reason)}
    except Exception as pe_err:
        return {'result': 'failed', 'error': str(pe_err)}


