def loadScenario(session_id, sce, host=socketAddress, port=socketPort, restVer="1.0.1"):
    """
    Load given scenario

    :param sessionId: session_id of the current test session
    :param sce: name of the sce filefilename to be loaded.
                Actually the file is sent to Airmosaic through the storeZipArchive method.
    :param host: IP address at which Airmosaic is listening
    :param port: port at which Airmosaic is listening
    :return: {'result':result, 'error':error},
             where *result* can be *success* or *failed* and
             *error* is the failure cause description.
    """
    #json_output = False
    #json_buffer = []
    if "," in sce:
        sce = sce.split(",")[0]
    if restVer.startswith('1.'):
        return loadAirmosaicFile(session_id, sce, host=host, port=port, restVer=restVer)
    pe_log(json_output, json_buffer,
           '*DEBUG* pymosaic.loadScenario(): reply in legacy mode.')
    airmosaic_cmd = json.dumps({
        'cmd': 'loadScenario',
        'params': {
            'sessionId': session_id,
            'scenarioFilename': sce
        }
    })
    req = Request('http://%s:%s/amJsonInterface' % (host, port), airmosaic_cmd.encode('utf-8'), headers)
    try:
        res = urlopen(req, timeout=URLOPEN_TIMEOUT).read().decode('utf-8')
        return json.loads(res)
    except URLError as pe_err:
        return {'result': 'failed', 'error': str(pe_err.reason)}
    except Exception as err:
        return {'result': 'failed',
                'error': "connection to Harness({0}) failed, error: {1}"
                         .format("http://%s:%s/amJsonInterface (timeout=%s)" %
                                 (host, port, str(URLOPEN_TIMEOUT)), str(err))}


def getStatus(session_id, host=socketAddress, port=socketPort, restVer="1.0.1"):
    """
    Get scenario execution status

    :param sessionId: session_id of the current test session
    :param host: IP address at which Airmosaic is listening
    :param port: port at which Airmosaic is listening
    :return: {'result':result, 'error':error, 'status':status}, where *result* can be *success* or *failed*,
            *error* is the failure cause and
            *status* can be set to: NONE, SIMINIT_AVAILABLE_INVALID, SIMINIT_AVAILABLE,
            RUNNING_SIMINIT, RUNNING_SIMINIT_SCEAVAIL, SIMINIT_COMPLETED, SCENARIO_AVAILABLE,
            SCENARIO_RUNNABLE, RUNNING_SCENARIO, SCENARIO_COMPLETED, ABNORMAL_FAIL, SID_OPENING
    """
    if restVer.startswith('1.'):
        return getAirmosaicStatus(session_id, host=host, port=port, restVer=restVer)
    #pe_log(json_output, json_buffer,
    #       '*DEBUG* pymosaic.getStatus(): reply in legacy mode.')
    airmosaic_cmd = json.dumps({
        'cmd': 'getStatus',
        'params': {
            'sessionId': session_id
        }
    })
    req = Request('http://%s:%s/amJsonInterface' % (host, port), airmosaic_cmd.encode('utf-8'), headers)
    try:
        res = urlopen(req, timeout=URLOPEN_TIMEOUT).read().decode('utf-8')
        return json.loads(res)
    except URLError as pe_err:
        return {'result': 'failed', 'error': 'pymosaic.getStatus() failing for: %s'% pe_err, 'status': ''}
    except Exception as pe_err:
        return {'result': 'failed', 'error': 'pymosaic.getStatus() failing for: %s'% pe_err, 'status': ''}


