def getTestResult(session_id, host=socketAddress, port=socketPort, restVer="1.0.1", **kwargs):
    """
    Get final test result in XML format, after scenario execution end

    :param sessionId: session_id of the current test session
    :param host: IP address at which Airmosaic is listening
    :param port: port at which Airmosaic is listening
    :return: {'result':result, 'error':error, 'testResult':testResult},
             where *result* can be *success* or *failed*,
             *error* is the failure cause and
             *testResult* is an XML string containing a summary of the test execution result.
    """
    #json_output = False
    #json_buffer = []
    if 'filename' in kwargs:
        filename = kwargs['filename']
    else:
        filename = ''
    if restVer.startswith('1.'):
        return getResult(session_id, filename=filename, host=host, port=port, restVer=restVer)
    pe_log(json_output, json_buffer,
           '*DEBUG* pymosaic.getTestResult(): reply in legacy mode.')
    airmosaic_cmd = json.dumps({
        'cmd': 'getTestResult',
        'params': {
            'sessionId': session_id
        }
    })
    req = Request('http://%s:%s/amJsonInterface' % (host, port),
                  airmosaic_cmd.encode('utf-8'), headers)
    try:
        res = urlopen(req, timeout=URLOPEN_TIMEOUT).read().decode('utf-8')
        res = json.loads(res)
    except URLError as pe_err:
        return {'result': 'failed', 'error': str(pe_err.reason)}
    if (res['result'] == 'success') and (filename != ''):
        try:
            #pe_log(json_output, json_buffer, "*DEBUG* pymosaic.getTestResult(): creating file="+str(filename))
            outfile = open(filename, 'wt')
            outfile.write(res['testResult'])
            outfile.close()
            res['testResult'] = filename
        except Exception as pe_err:
            pe_log(json_output, json_buffer, "*DEBUG* pymosaic.getTestResult(): cannot save file,error="+str(pe_err))
            res['error'] = 'Error saving Test result archive to %s' % filename
            res['result'] = 'failed'
    return res


