def getBugreport(session_id, host=socketAddress, port=socketPort, restVer="1.0.1", **kwargs):
    """
    Generate and get the bugreport archive.
    equivalent to GUI command menu->Tools->collect all logs referred to the las test execution.

    :param sessionId: session_id of the current test session
    :param host: IP address at which Airmosaic is listening
    :param port: port at which Airmosaic is listening
    :param filename(optional): If present, bugreport is saved on the filename file
    :return: {'result': result,
              'error': error,
              'bugreportFile': bugreportFile},
              where *result* can be *success* or *failed*,
              *error* is the failure cause in case of error and
              *bugreportFile* is the base64 encoded bugreport.
    """
    #json_output = False
    #json_buffer = []
    if 'filename' in kwargs:
        filename = kwargs['filename']
    else:
        filename = ''
    if restVer.startswith('1.'):
        return bugreport(session_id, filename=filename, host=host, port=port, restVer=restVer)
    else:
        pe_log(json_output, json_buffer,
               '*DEBUG* pymosaic.getBugreport(): reply in legacy mode.')
    airmosaic_cmd = json.dumps({
        'cmd': 'getBugreport',
        'params': {
            'sessionId': session_id
        }
    })
    req = Request('http://%s:%s/amJsonInterface' % (host, port),
                  airmosaic_cmd.encode('utf-8'), headers)
    try:
        res = urlopen(req, timeout=600).read().decode('utf-8')
        res = json.loads(res)
    except URLError as pe_err:
        return {'result': 'failed', 'error': str(pe_err.reason)}
    except Exception as pe_err:
        return {'result': 'failed', 'error': str(pe_err)}
    if 'result' in res:
        if (res['result'] == 'success') and (filename != ''):
            try:
                outfile = open(filename, 'wb')
                outfile.write(base64.b64decode(res['bugreportFile']))
                outfile.close()
                res['bugreportFile'] = filename
            except Exception as pe_err:
                pe_log(json_output, json_buffer, "*WARN* "+str(pe_err))
                res['error'] = 'Error saving bugreport archive to %s' % filename
                res['result'] = 'failed'
    return res


