def getHarnessStats(host=socketAddress, port=socketPort, restVer="1.0.1"):
    """
    Get session activity statistics

    :param host: IP address at which Airmosaic is listening
    :param port: port at which Airmosaic is listening
    :return: {result: "sucess|failed",
              error: "",
              activeSessionStats: []},
              where  *result* can be *success* or *failed*,
              *error* is the failure cause description in case of error
              *activeSessionStats* is a structure described here:
                {sessionId: "6016d604-4c76-4ddd-99f0-c6940c25b525",
                 taskList: [{date: "Fri Sep 16 14:33:21 CEST 2016",
                             result: "sucess|failed",error: ""}...]}
    """
    if restVer.startswith('1.'):
        return harnessStats(host=host, port=port)
    pe_log(json_output, json_buffer,
           '*DEBUG* pymosaic.getHarnessStats(): reply in legacy mode.')
    airmosaic_cmd = json.dumps({'cmd': 'getHarnessStats', 'params': {}})
    req = Request('http://%s:%s/amJsonInterface' % (host, port),
                  airmosaic_cmd.encode('utf-8'), headers)
    try:
        res = urlopen(req, timeout=URLOPEN_TIMEOUT).read().decode('utf-8')
        return json.loads(res)
    except URLError as pe_err:
        return {'result': 'failed', 'error': str(pe_err.reason)}
    except Exception as pe_err:
        return {'result': 'failed', 'error': str(pe_err)}


def getScenarioLogger(session_id,
                      host=socketAddress,
                      port=socketPort,
                      startId="",
                      endId="",
                      restVer="1.0.1"):
    """
    return a copy of the scenario logger file
    :param sessionId: session_id of the current test session
    :param host: IP address at which Airmosaic is listening
    :param port: port at which Airmosaic is listening
    :param startId: starting line number in the scenario logger to be reported,
                    if obmitted all the line from the beginning are collected
    :param endId: finish line number in the scenario logger to be reported,
                  if obmitted all the line untill the end are collected
    :return: {result: "sucess|failed", error:"", logRecords: [.]},\n
            where *result* can be *success* or *failed*,\n
            *error* is the failure cause, \n
            *logreport* is an array of structure defined as:\n
            {'recordId': record,
             'datetime': datetime,
             'instance': instance,
             'messageLevel': messageLevel,
             'category': category,
             'message': message,
             'group': group}

    |

    :example: getScenarioLogger("xyz")
    :example output:\n
        {\n
            result: "sucess|failed"\n
            error:""\n
            logRecords: [\n
                    {\n
                        recordId: 1,\n
                        datetime: 13918,\n
                        instance: "New Subscriber",\n
                        messageLevel: "ERROR",\n
                        category: "Subscribers",\n
                        message: "CLIPdpActivate: Invalid procedure (Cell=0)",\n
                        group: "sg1"\n
                    },\n
                    ...\n
                    ]\n
        }\n
    """
    if restVer.startswith('1.'):
        return scenarioLogger(session_id, startId=startId, endId=endId, host=host, port=port, restVer=restVer)
    pe_log(json_output, json_buffer,
           '*DEBUG* pymosaic.getScenarioLogger(): reply in legacy mode.')
    if isinstance(startId, int):
        startId = str(startId)
    if isinstance(endId, int):
        endId = str(endId)
    #if len(startId) == 0 and len(endId) == 0:
    if not startId == 0 and not endId:
        airmosaic_cmd = json.dumps({
            'cmd': 'getScenarioLogger',
            'params': {
                'sessionId': session_id
            }
        })
    #elif len(startId) == 0 and endId:
    elif not startId == 0 and endId:
        airmosaic_cmd = json.dumps({
            'cmd': 'getScenarioLogger',
            'params': {
                'sessionId': session_id,
                'endId': endId
            }
        })
    #elif startId and len(endId) == 0:
    elif startId and not endId:
        airmosaic_cmd = json.dumps({
            'cmd': 'getScenarioLogger',
            'params': {
                'sessionId': session_id,
                'startId': startId
            }
        })
    else:
        airmosaic_cmd = json.dumps({
            'cmd': 'getScenarioLogger',
            'params': {
                'sessionId': session_id,
                'startId': startId,
                'endId': endId
            }
        })
    req = Request('http://%s:%s/amJsonInterface' % (host, port),
                  airmosaic_cmd.encode('utf-8'), headers)
    try:
        res = urlopen(req, timeout=URLOPEN_TIMEOUT).read().decode('utf-8')
        return json.loads(res)
    except URLError as pe_err:
        return {'result': 'failed', 'error': str(pe_err.reason)}
    except Exception as pe_err:
        return {'result': 'failed', 'error': str(pe_err)}


