def getGroups(session_id, host=socketAddress, port=socketPort, restVer="1.0.1"):
    """
    Retrieve groups' names from scenario

    :param sessionId: session_id of the current test session
    :param host: IP address at which Airmosaic is listening
    :param port: port at which Airmosaic is listening

    :return: {'result':'success' | 'failed', 'error': failure_cause}

    :example: getGroups("86e66923-8b1e-4b01-91de-044625dcbe32")

    :sample output: {'result': 'success', 'error': ''}
    """
    #pe_log(False, [], "*DEBUG* pymosaic.getGroups(): session_id={0}".format(session_id))
    #pe_log(False, [], "*DEBUG* pymosaic.getGroups(): host={0}".format(host))
    #pe_log(False, [], "*DEBUG* pymosaic.getGroups(): port={0}".format(port))
    #pe_log(False, [], "*DEBUG* pymosaic.getGroups(): restVer={0}".format(restVer))
    if restVer.startswith('1.'):
        #return groups(session_id, method="GET", operation="", groupName="", host=host, port=port)
        return groups(session_id, host=host, port=socketPort, restVer="")
    pe_log(json_output, json_buffer,
           '*DEBUG* pymosaic.getGroups(): reply in legacy mode.')
    airmosaic_cmd = json.dumps({'cmd': 'getGroups', 'params': {'sessionId':session_id}})
    req = Request('http://%s:%s/amJsonInterface' % (host, port), airmosaic_cmd.encode("utf-8"), headers)
    try:
        res = urlopen(req, timeout=URLOPEN_TIMEOUT).read().decode('utf-8')
        lgroups = []
        ghj = json.loads(res)
        for elem in ghj["groups"]:
            lgroups.append(elem.split(':')[0][:-1])
        ghj['groups'] = lgroups
        return json.loads(res)
    except URLError as pe_err:
        return {'result': 'failed', 'error': str(pe_err.reason)}
    except Exception as pe_err:
        return {'result': 'failed', 'error': str(pe_err)}


def startGroup(session_id, groupName, host=socketAddress, port=socketPort, restVer="1.0.1"):
    """
    Start scenario running only group specified by groupName, other groups remain on pause.

    :param sessionId: session_id of the current test session
    :param groupName: name of a scenario's group
    :param host: IP address at which Airmosaic is listening
    :param port: port at which Airmosaic is listening

    :return: {'result':'success' | 'failed', 'error': failure_cause}

    :example: startGroup("86e66923-8b1e-4b01-91de-044625dcbe32", "Group1")

    :sample output: {'result': 'success', 'error': ''}
    """
    if restVer.startswith('1.'):
        return groups(session_id, "POST", "startGroup", groupName, host, port, restVer)
    airmosaic_cmd = json.dumps({"cmd":"startGroup", "params":{'sessionId':session_id, 'groupName': groupName}})
    req = Request('http://%s:%s/amJsonInterface' % (host, port), airmosaic_cmd.encode("utf-8"), headers)
    try:
        res = urlopen(req, timeout=URLOPEN_TIMEOUT).read().decode('utf-8')
        return json.loads(res)
    except URLError as pe_err:
        return {'result': 'failed', 'error': str(pe_err.reason)}
    except Exception as pe_err:
        return {'result': 'failed', 'error': str(pe_err)}


