def getAirmosaicVersion(path):
    """

    :example: devicesDb(sesId, method="GET", parName="FreqBand", userId="1", host="192.168.1.10", port="8090")
    :example: devicesDb(sesId, method="POST", parName="FreqBand", iserId="1", host="192.168.1.10", port="8090")

    :sample output:
    :sample output:
    """
    if "airmosaic_lteuu-" in path:
        version = path.split("airmosaic_lteuu-")[1:][0]
    elif "AirMosaic LTE Uu" in path:
        version = path.split("AirMosaic LTE Uu")[1:][0]
    else:
        version = "UnkownRC_0.0.0"
    print (version)
    major = version.split("RC")[0].split(".")[0]
    minor = (".".join(version.split("RC")[0].split(".")[1:]))
    rc = version.split("RC")[1].split("/")[0]
    print ("M:%s Min:%s RC:%s"%(major,minor,rc))
    return (major,minor,rc)


