def checkTestResult(result_xml, **kwargs):
    """
    Parse Airmosaic xml file got from getTestResult API
    Input arguments are:

    :paramr result_xml: string containing the Airmosaic test result xml
    :param path(optional): full path and name of the saved result xml.
                           If present, check is done on the xml file, result_xml string otherwise
    :return: return {'output': <output>, 'result': success/failed, 'error': <array of errors if any>}

    :example: checkTestResult('',path='/tmp/Result.xml')
    :example output: {'output': 'No Error', 'result': 'success', 'error': ''}
    """
    result_checks = []
    path = ""
    #pe_log(json_output, json_buffer, args
    if 'path' in kwargs:
        path = kwargs['path']
        resultfile = open(path, "r")
        result_xml = resultfile.read()
    if result_checks and path == "":
        return {'result': 'failed', 'error': 'Nothing to check', 'output': ''}
    try:
        root = ET.fromstring(result_xml)
    except ExpatError:
        return {
            'result': 'failed',
            'error': 'Wrong Test Result format',
            'output': 'No Error'
        }
    #root = result_tree.getroot()
    #succ_checks = 0
    errdescr = []
    toterr = 0
    for elem in root.iter('TestProcedure'):
        #pe_log(json_output, json_buffer,
        #       "*DEBUG* pymosaic.checkTestResult(): child attribs={testname}".format(testname= elem.attrib)
        #pe_log(json_output, json_buffer,
        #       "*DEBUG* pymosaic.checkTestResult(): number of failure={nerrors}"
        #       .format(nerrors= elem.attrib.get('NumFailure'))
        if (elem.attrib.get('NumFailure') != '0' and
                elem.attrib.get('NumFailure') != ''):
            sessionname = root.find('.//%s/..' % elem.tag)
            groupname = root.find('.//%s/..' % sessionname.tag)
            #pe_log(json_output, json_buffer, sessionname.tag,sessionname.attrib['SessionName']
            #pe_log(json_output, json_buffer, groupname.tag,groupname.attrib['GroupName']
            errdescr.append({
                'Group': groupname.attrib['GroupName'],
                'Session': sessionname.attrib['SessionName'],
                'TestProcedure': elem.attrib['TestProcedureKind'],
                'NumFailure': elem.attrib['NumFailure']
            })
            toterr = toterr + 1
    #pe_log(json_output, json_buffer, errdescr

    if errdescr == []:
        result = {'result': 'success', 'error': '', 'output': 'No Error'}
    else:
        result = {
            'result': 'failed',
            'error': 'Counter checks not passed.',
            'output': errdescr
        }
    return result


def buildCountersList(category, instances, counter_names):
    """
    Creates a counters list in the format accepted by Airmosaic python API

    :param category: counters category
    :param instances: list of counters instances
    :param counter_names: list of counters names
    :return: list of counters in the format accepted by *addCounters* and *removeCounters* methods

    :example: buildCountersList("Cells",['1', '2', '3'],["cPdschCrcOk", "cPhyCellId" ])
    :examle output: [{'category': 'Cells', 'instance': 1, 'name': 'cPdschCrcOk'},
                     {'category': 'Cells', 'instance': 1, 'name': 'cPhyCellId'},
                     {'category': 'Cells', 'instance': 2, 'name': 'cPdschCrcOk'},
                     {'category': 'Cells', 'instance': 2, 'name': 'cPhyCellId'},
                     {'category': 'Cells', 'instance': 3, 'name': 'cPdschCrcOk'},
                     {'category': 'Cells', 'instance': 3, 'name': 'cPhyCellId'}]
    """
    countersList = []
    for elem in instances:
        for counter_name in counter_names:
            countersList.append({
                'category': category,
                'instance': elem,
                'name': counter_name
            })
    return countersList


def buildCountersListFromFile(filename):
    """
    Creates the counters list starting from Airmosaic preferences archive

    :param filename: path to an Airmosaic preferences archive
    :return: list of counters in the format accepted by *addCounters* and *removeCounters* methods

    :example: buildCountersListFromFile("/tmp/counters.zip")
    :example output: [{'category': 'Cells', 'instance': '1', 'name': 'cPhyCellId'},
                      {'category': 'Cells', 'instance': '1', 'name': 'cPdschCrcOk'}]
    """
    json_output = False
    json_buffer = []
    sub_counters_dict = {}
    cells_counters_dict = {}
    beams_counters_dict = {}
    groups_counters_dict = {}
    counters_list = []
    try:
        counters_zip = zipfile.ZipFile(filename)
    except zipfile.BadZipfile:
        return []
    try:
        counters_list_file = counters_zip.open(
            'config/Preferences/com/prisma/modulecounters.properties'
        ).readlines()
        for line in counters_list_file:
            if 'loggingCountersSubscribers' in line:
                sub_counters_line = line[27:]
            if 'loggingCountersCells' in line:
                cells_counters_line = line[21:]
            if 'loggingCountersGroups' in line:
                groups_counters_line = line[22:]
            if 'loggingCountersDigitalBeams' in line:
                beams_counters_line = line[line.find("=")+1:]

        if len(sub_counters_line) > 10:
            instances = [
                elem.rsplit(':')[0] for elem in sub_counters_line.rsplit(';')
            ]
            counters = [
                elem.rsplit(':')[1].rsplit('|')[:-1]
                for elem in sub_counters_line.rsplit(';')
            ]
            for instance, counters_set in zip(instances, counters):
                sub_counters_dict[instance] = [
                    elem.rsplit(', ')[0] for elem in counters_set
                ]
            for instance in sub_counters_dict:#.keys():
                for counter in sub_counters_dict[instance]:
                    counters_list.append({
                        'category': 'Subscribers',
                        'instance': instance,
                        'name': counter
                    })
        if len(cells_counters_line) > 10:
            instances = [
                elem.rsplit(':')[0] for elem in cells_counters_line.rsplit(';')
            ]
            counters = [
                elem.rsplit(':')[1].rsplit('|')[:-1]
                for elem in cells_counters_line.rsplit(';')
            ]
            for instance, counters_set in zip(instances, counters):
                cells_counters_dict[instance] = [
                    elem.rsplit(', ')[0] for elem in counters_set
                ]
            for instance in cells_counters_dict:#.keys():
                for counter in cells_counters_dict[instance]:
                    counters_list.append({
                        'category': 'Cells',
                        'instance': instance,
                        'name': counter
                    })
        if len(beams_counters_line) > 10:
            instances = [
                elem.rsplit(':')[0] for elem in beams_counters_line.rsplit(';')
            ]
            counters = [
                elem.rsplit(':')[1].rsplit('|')[:-1]
                for elem in beams_counters_line.rsplit(';')
            ]
            for instance, counters_set in zip(instances, counters):
                beams_counters_dict[instance] = [
                    elem.rsplit(', ')[0] for elem in counters_set
                ]
            for instance in beams_counters_dict:#.keys():
                for counter in beams_counters_dict[instance]:
                    counters_list.append({
                        'category': 'DigitalBeams',
                        'instance': instance,
                        'name': counter
                    })
        if len(groups_counters_line) > 10:
            instances = [
                elem.rsplit(':')[0]
                for elem in groups_counters_line.rsplit(';')
            ]
            counters = [
                elem.rsplit(':')[1].rsplit('|')[:-1]
                for elem in groups_counters_line.rsplit(';')
            ]
            for instance, counters_set in zip(instances, counters):
                groups_counters_dict[instance] = [
                    elem.rsplit(', ')[0] for elem in counters_set
                ]
            for instance in groups_counters_dict:#.keys():
                for counter in groups_counters_dict[instance]:
                    counters_list.append({
                        'category': 'Groups',
                        'instance': instance,
                        'name': counter
                    })
    except Exception as pe_err:
        json_output = False
        json_buffer = []
        pe_log(json_output, json_buffer, "*INFO* " + str(pe_err))
        return []
    counters_zip.close()
    return counters_list


def buildcounters_to_logListFromFile(filename, cells=[], beams=[], amversion=["8", "16.0", "Any"]):

    """
    Create a list of counters to be logged to csv files starting from an Airmosaic preferences archive

    :param filename: path to an Airmosaic preferences archive
    :return: list of counters in the format accepted by *logCountersToFile* method
    """
    #sub_counters_dict = {}
    #cells_counters_dict = {}
    #groups_counters_dict = {}
    counters_list = []
    json_output = False
    json_buffer = []
    sub_counters_line = ""
    cells_counters_line = ""
    beams_counters_line = ""
    groups_counters_line = ""
    try:
        counters_zip = zipfile.ZipFile(filename)
    except (zipfile.BadZipfile, IOError, Exception) as pe_err:
        pe_log(json_output, json_buffer, "*INFO* buildCountersToLogListFromFile(): " + str(pe_err))
        return []
    try:
        counters_list_file = counters_zip.open(
            'config/Preferences/com/prisma/modulecounters.properties').read(
            ).decode('utf-8').splitlines()
        for line in counters_list_file:
            if 'loggingCountersSubscribers' in line:
                sub_counters_line = line[27:]
            if 'loggingCountersCells' in line:
                cells_counters_line = line[21:]
            if 'loggingCountersGroups' in line:
                groups_counters_line = line[22:]
            if 'loggingCountersDigitalBeams' in line:
                beams_counters_line = line[line.find("=")+1:]
        if len(sub_counters_line) > 10:
            instances = [
                elem.rsplit(':')[0] for elem in sub_counters_line.rsplit(';')
            ]
            #print (sub_counters_line.rsplit(';'))
            counters = [
                elem.rsplit(':')[1].rsplit('|')[:-1]
                for elem in sub_counters_line.rsplit(';')
            ]
            nameAndPathList=[]
            oneue = False
            for instance, counters_set in zip(instances, counters):
                #print (instance, counters_set)
                #nameAndPathList =[]
                if not oneue:
                    for elem in counters_set:
                        elem = get_counter_name_version(elem,minor=amversion[1])
                        nameAndPathList.append({'nameAndPath': elem})
                        
                    oneue = True
                counters_list.append({
                    'category':
                    'Subscribers',
                    'instance':
                    instance,
                    'nameAndPathList': nameAndPathList
                })
        #print (counters_list)
        if len(cells_counters_line) > 10:
            instances = [
                elem.rsplit(':')[0] for elem in cells_counters_line.rsplit(';')
            ]
            instances = list(set(instances))
            pe_log(json_output, json_buffer,
                   "*DEBUG* pymosaic.buildcounters_to_logListFromFile(): instances=" + str(instances))
            counters = [
                elem.rsplit(':')[1].rsplit('|')[:-1]
                for elem in cells_counters_line.rsplit(';')
            ]
            pe_log(json_output, json_buffer,
                   "*DEBUG* pymosaic.buildcounters_to_logListFromFile(): COUNTERS=" + str(counters))
            if cells != []:
                #remap cells and add beam cell
                instances = []
                for cel in cells:
                    instances.append(cel)
            #Add also countersd for each cell beam
            if beams != []:
                print ("BEAMS %s"%beams)
                for beamcell in beams:
                    instances.append(beamcell.split("_")[0])
            #print (instances)
            #print (counters)
            instances = list(set(instances))
            for instance in instances:
                for counters_set in counters:
                    counters_list.append({
                        'category':
                        'Cells',
                        'instance':
                        instance,
                        'nameAndPathList': [{
                            'nameAndPath': elem
                        } for elem in counters_set]
                })
        if len(beams_counters_line) > 10:
            instances = [
                elem.rsplit(':')[0] for elem in beams_counters_line.rsplit(';')
            ]
            #overwrite istances if passed from scenario
            if beams:
                instances = []
                for beam in beams:
                    instances.append(beam)
            pe_log(json_output, json_buffer,
                   "*DEBUG* pymosaic.buildcounters_to_logListFromFile(): instances=" + str(instances))
            counters = [
                elem.rsplit(':')[1].rsplit('|')[:-1]
                for elem in beams_counters_line.rsplit(';')
            ]
            pe_log(json_output, json_buffer,
                   "*DEBUG* pymosaic.buildcounters_to_logListFromFile(): COUNTERS=" + str(counters))
            nameAndPathList=[]
            instances = list(set(instances))
            try: 
                for elem in counters[0]:
                    #Handle different counter version for <13 and >=v14 and >=16
                    elem = get_counter_name_version(elem,minor=amversion[1])
                    nameAndPathList.append({'nameAndPath': elem})
                for instance in instances:
                        counters_list.append({
                            'category':
                            'DigitalBeams',
                            'instance':
                            instance,
                            'nameAndPathList': nameAndPathList 
                    })
            except Exception as e:
                pe_log(json_output, json_buffer, "*WARN* %s" + str(e))
            
        if len(groups_counters_line) > 10:
            instances = [
                elem.rsplit(':')[0]
                for elem in groups_counters_line.rsplit(';')
            ]
            counters = [
                elem.rsplit(':')[1].rsplit('|')[:-1]
                for elem in groups_counters_line.rsplit(';')
            ]
            for instance, counters_set in zip(instances, counters):
                counters_list.append({
                    'category':
                    'Groups',
                    'instance':
                    instance,
                    'nameAndPathList': [{
                        'nameAndPath': elem
                    } for elem in counters_set]
                })
    except Exception as pe_err:
        pe_log(json_output, json_buffer, "*INFO* " + str(pe_err))
        return []
    counters_zip.close()
    return counters_list


def setGlobalVariables(sid, variables, restVer="1.0.1"):
    """
    Change the values of global variables in the given sid with those passed in the *variables* list.
    This will modify the sid.
    Please consider using the setGlobalVariable API to change global variable on Airmosaic runtime

    :param sid: path to sid file to be edited
    :param variables: list of dictionaries each containing a name/value pair:
                    [{'name':variable_name, 'value':variable_value},...]
    :return: {'result':'success|failed', 'error':''}

    :example: setGlobalVariables("/tmp/Test.sid",
                                 [{'name':'ftpuser', 'value':'user'},{'name':'ftppassword', 'value':'user'}])
    :example output: {'result':'success', 'error':''}
    """
    if isinstance(variables, str) and variables:
        variables = ast.literal_eval(variables)
    if variables != '':
        try:
            sid_xml = ET.parse(sid)
        except ExpatError:
            return {'result': 'failed', 'error': 'Wrong sid file format'}
        sid_root = sid_xml.getroot()
        sid_globals = sid_root.findall('.//globals/variable')
        if sid_globals:
            for elem in variables:
                for sid_global in sid_globals:
                    if elem['name'] == sid_global.get('name'):
                        sid_global.set('value', elem['value'])
        sid_xml.write(sid)
    return {'result': 'success', 'error': ''}


def getGlobalVariables(sid, restVer="1.0.1"):
    """
    Get the values of global variables in the given sid with those passed in the *variables* list.
    This will modify the sid.
    Please consider using the setGlobalVariable API to change global variable on Airmosaic runtime

    :param sid: path to sid file to be edited
    :param variables: list of dictionaries each containing a name/value pair:
                    [{'name':variable_name, 'value':variable_value},...]
    :return: {'result':'success|failed', 'error':''}

    :example: setGlobalVariables("/tmp/Test.sid",
                                 [{'name':'ftpuser', 'value':'user'},{'name':'ftppassword', 'value':'user'}])
    :example output: {'result':'success', 'error':''}
    """
    try:
        sid_xml = ET.parse(sid)
    except ExpatError:
        return {'result': 'failed', 'error': 'Wrong sid file format'}
    sid_root = sid_xml.getroot()
    amglobals = {}
    try:
        sid_globals = sid_root.findall('.//globals/variable')
        if sid_globals:
            for sid_global in sid_globals:
                amglobals[sid_global.get('name')] = sid_global.get('value')
    except Exception as e:
        pe_log(json_output, json_buffer,
           '*DEBUG* pymosaic.getGlobalVariables(): %s' %
           (e))
    return amglobals


def checkForCountersContinuous(session_id,
                               checklist,
                               host=socketAddress,
                               port=socketPort,
                               **kwargs):
    """
    If the test is running in background this function is useful to set a trigger on a single counter
    or on a list of counters.
    This function returns eithern when test finish, or one between timeout and counter trigger become True

    :param sessionId: session id of the test given by openTestSession API
    :param checklist: list of counter to check
    :param timeout(optional): timeout for the function
    :param polling_timer(optional): value in second between each counter polling, default=5
    :param single_counter_trigger: True or False, when True only one counter matching criteria will stop the function,
                                   otherwise function is stopped when all counters match criteria.
    :param airmosaic_ip(optional): Airmosaic IP in case it run on a different host
    :param airmosaic_port(optional): Airmosaic Harness port in case it's different from 8090

    :example: checkForCountersContinuous('21737931-58c8-45ac-afa7-27896be07177',
                                         [{'category': 'Cells',
                                           'instance': "1",
                                           'name': 'cPdschThroughput',
                                           'check':'>', 'checkvalue':'3000000'}],
                                         timeout=50,
                                         single_counter_trigger=True)
    :example output: {'result': 'failed',
                      'procedure': 'waitCounters',
                      'error': "50s timeout expired. Last counters values: [
                            {u'category': u'Cells',
                                u'instance': u'1',
                                u'name': u'cPdschThroughput',
                                u'value': u'8000.000'}]"}
    """
    polling_timer = 5
    timeout = 0
    json_output = False
    json_buffer = []
    if 'polling_timer' in kwargs:
        polling_timer = int(kwargs['polling_timer'])
    if 'timeout' in kwargs:
        timeout = int(kwargs['timeout'])
    if 'single_counter_trigger' in kwargs:
        single_counter_trigger = int(kwargs['single_counter_trigger'])
    else:
        single_counter_trigger = False
    timeout_exp = time.time() + timeout
    pe_log(json_output, json_buffer,
           '*DEBUG* pymosaic.checkForCountersContinuous(): Current time: %d\nExpiration time: %d' %
           (time.time(), timeout_exp))
    while True:
        try:
            counters_list = getCounters(session_id, host, port)['counters']
            pe_log(json_output, json_buffer,
                   '*DEBUG* pymosaic.checkForCountersContinuous(): Counters list: %s' % counters_list)
        except KeyError:
            return {
                'result': 'failed',
                'procedure': 'waitCounters',
                'error': 'Error polling counters'
            }
        succ_checks = 0
        for elem in counters_list:
            pe_log(json_output, json_buffer, '*DEBUG* pymosaic.checkForCountersContinuous(): elem list: %s' % elem)
            for checkelem in checklist:
                if checkelem['instance'] == elem['instance']:
                    if checkelem['category'] == elem['category']:
                        if checkelem['name'] == elem['name']:
                            pe_log(
                                json_output, json_buffer,
                                '*DEBUG* pymosaic.checkForCountersContinuous(): Element to check: %s\nCheck threshold: %s'
                                % (elem, checkelem))
                            if checkelem['check'] == '>':
                                if 'value' in elem:
                                    if int(float(elem['value'])) > int(checkelem['checkvalue']):
                                        succ_checks += 1
                            elif checkelem['check'] == '>=':
                                if int(elem['value']) >= int(
                                        checkelem['checkvalue']):
                                    succ_checks += 1
                            elif checkelem['check'] == '==':
                                if int(elem['value']) == int(
                                        checkelem['checkvalue']):
                                    succ_checks += 1
                            elif checkelem['check'] == '<':
                                if int(elem['value']) < int(
                                        checkelem['checkvalue']):
                                    succ_checks += 1
                            elif checkelem['check'] == '<=':
                                if int(elem['value']) <= int(
                                        checkelem['checkvalue']):
                                    succ_checks += 1
        if single_counter_trigger is True:
            if succ_checks != 0:
                pe_log(json_output, json_buffer, ("*DEBUG* pymosaic.checkForCountersContinuous(): " + "Foundsingle"))
                break
        else:
            if succ_checks == len(checklist):
                pe_log(json_output, json_buffer, ("*DEBUG* pymosaic.checkForCountersContinuous(): " + "FoundMulti"))
                break
        res = getStatus(session_id, host, port)
        pe_log(json_output, json_buffer, ("*DEBUG* pymosaic.checkForCountersContinuous(): getstatus.res=" + str(res)))
        if res['status'] != 'RUNNING_SCENARIO':
            pe_log(json_output, json_buffer,
                   ("*DEBUG* pymosaic.checkForCountersContinuous(): " + "Scenario not runnign anymore"))
            return {'result': 'success', 'info': 'scenario ended'}
        if (time.time() > timeout_exp) and (timeout > 0):
            return {
                'result':
                'failed',
                'procedure':
                'waitCounters',
                'error':
                '%ds timeout expired. Last counters values: %s' %
                (timeout, str(counters_list))
            }
        time.sleep(polling_timer)
    return {'result': 'success', 'info': counters_list}


def checkForCounters(
                     counters_list,
                     checklist,
                     host=socketAddress,
                     port=socketPort,
                     **kwargs):
    """
    If the test is running in background this function is useful to set a trigger on a single counter
    or on a list of counters.
    This function returns eithern when test finish, or one between timeout and counter trigger become True

    :param sessionId: session id of the test given by openTestSession API
    :param checklist: list of counter to check
    :param timeout(optional): timeout for the function
    :param polling_timer(optional): value in second between each counter polling, default=5
    :param single_counter_trigger: True or False, when True only one counter matching criteria will stop the function,
                                   otherwise function is stopped when all counters match criteria.
    :param airmosaic_ip(optional): Airmosaic IP in case it run on a different host
    :param airmosaic_port(optional): Airmosaic Harness port in case it's different from 8090

    :example: checkForCounters('21737931-58c8-45ac-afa7-27896be07177',
                                         [{'category': 'Cells',
                                           'instance': "1",
                                           'name': 'cPdschThroughput',
                                           'check':'>', 'checkvalue':'3000000'}],
                                         timeout=50,
                                         single_counter_trigger=True)
    :example output: {'result': 'failed',
                      'procedure': 'waitCounters',
                      'error': "50s timeout expired. Last counters values: [
                            {u'category': u'Cells',
                                u'instance': u'1',
                                u'name': u'cPdschThroughput',
                                u'value': u'8000.000'}]"}
    """

    from operator import eq, ne, gt, lt, le, ge
    json_output = False
    json_buffer = []
    succ_checks = 0
    rules = {
            "gt": gt,
            "ne": ne,
            "eq": eq,
            "lt": lt,
            "le": le,
            "ge": ge,
            }
    if not counters_list or not checklist:
        return {'result': 'success', 'info': counters_list}
    if "counters" in counters_list:
        counters_list = counters_list['counters']
    result="success"

    checklist = checklist.split("|")
        #counters_list = [{'category': 'Cells', 'instance': '2', 'name': 'cUeAttached', 'value': '1'}, {'category': 'Cells', 'instance': '1', 'name': 'cUeAttached', 'value': '0'}, {'category': 'DigitalBeams', 'instance': '1_0', 'name': 'bNrPdschGenTbBler', 'value': '0.000'}, {'category': 'Cells', 'instance': '2', 'name': 'cPdschThroughput', 'value': '8000.000'}, {'category': 'Cells', 'instance': '2', 'name': 'cPhichNakRatio', 'value': '0.000'}, {'category': 'Cells', 'instance': '2', 'name': 'cActiveRrcConnections', 'value': '1'}, {'category': 'DigitalBeams', 'instance': '1_0', 'name': 'bNrPuschGenTotThroughput', 'value': '0.000'}, {'category': 'DigitalBeams', 'instance': '1_0', 'name': 'bNrPdschGenTotThroughput', 'value': '0.000'}, {'category': 'Cells', 'instance': '2', 'name': 'cPdschBler', 'value': '0.232'}, {'category': 'Cells', 'instance': '1', 'name': 'cActiveRrcConnections', 'value': '0'}, {'category': 'Cells', 'instance': '2', 'name': 'cPuschThroughput', 'value': '8000.000'}]
    if counters_list:
        for elem in counters_list:
            pe_log(json_output, json_buffer, '*DEBUG* pymosaic.checkForCounters(): elem list: %s' % elem)
            for checkelem in checklist:
                #keep Same rules as KPi check at end of test
                checkelem= checkelem.split(",")
                #0= Category
                #1= Instance
                #2= Name
                #3= Type (always last value here)
                #4= check
                #5= value
                category = elem['category'].replace("DigitalBeams","Beam").replace("Cells","Cell")
                name = elem['name']
                #print ("Checking %s %s "%(checkelem , elem))
                #print ("First Check %s %s "%(checkelem[1] , elem['instance']))
                if checkelem[1] == elem['instance'] or checkelem[1]=="All":
                    
                    if checkelem[0] == category:
                        #print ("Second Check %s %s "%(checkelem[0] , category))
                        #print ("Third Check %s %s "%(checkelem[2] , name))
                        if checkelem[2] == name:
                            pe_log(
                                json_output, json_buffer,
                                '*DEBUG* pymosaic.checkForCounters(): Element to check: %s\nCheck threshold: %s'
                                % (elem, checkelem[2]))
                            if checkelem[4] in  rules:
                                    foperator = rules[checkelem[4] ]
                            else:
                                foperator = gt
                            if 'value' in elem:
                                pe_log(json_output, json_buffer, ("*DEBUG* Checking %s %s %s %s"%(float(checkelem[5]),foperator,float(elem['value']),foperator(float(checkelem[5]) , float(elem['value'])))))
                                if foperator(float(checkelem[5]) , float(elem['value'])):
                                    succ_checks += 1
    if succ_checks != 0:
        pe_log(json_output, json_buffer, ("*WARN* pymosaic.checkForCounters(): Found %s errors checking counters"%succ_checks))
        result="failed"

    return {'result': result, 'info': counters_list}


def load_counters_configuration(counters_path):

    counters_zip = zipfile.ZipFile(counters_path)
    counters_content = {'cells': [], 'subscribers': [], 'groups': [],  'beams': []}
    counters_list=[]
    try:
        counters_list = counters_zip.open(
            'config/Preferences/com/prisma/modulecounters.properties').readlines()
        logitem = {'loggingCountersCells':'cells','loggingCountersSubscribers':'subscribers', 'loggingCountersGroups':'groups', 'loggingCountersDigitalBeams':'beams'}
        for elem in counters_list:
            elem = elem.decode('utf-8')
            try:
                #print (elem[:elem.find('=')-1])
                cntname = elem[:elem.find('=')]
                counters_list = elem[elem.find(('='))+1:]
                #print ( counters_list )
                if counters_list != '\n':
                    instance_list = counters_list.rsplit((';'))
                    print (instance_list)
                    for instance in instance_list:
                        print ("Adding %s %s"%(logitem[cntname], instance))
                        if instance not in counters_content[logitem[cntname]]:
                            counters_content[logitem[cntname]].append(instance)
            except:
                pass
    
    except Exception as e:
        traceback.print_exc()
        print ('Error opening airmosaic preferences file (%s)' % counters_path+str(e))
    counters_zip.close()
    return json.dumps(counters_content)

